package module

import (
	gcpidentityplatformtenantv1alpha1 "github.com/plantonhq/planton/catalog/gcp/gcpidentityplatformtenant/v1alpha1"
	"github.com/pulumi/pulumi/sdk/v3/go/pulumi"
)

// Locals mirrors the Terraform module's locals {} convention. The tenant's
// resource ID is generated by GCP (display_name is the only naming input)
// and none of its resources carry labels, so the only local is the
// resolved target.
type Locals struct {
	GcpIdentityPlatformTenant *gcpidentityplatformtenantv1alpha1.GcpIdentityPlatformTenant
}

func initializeLocals(_ *pulumi.Context, iacInput *gcpidentityplatformtenantv1alpha1.GcpIdentityPlatformTenantIacInput) *Locals {
	return &Locals{
		GcpIdentityPlatformTenant: iacInput.Target,
	}
}
